#!/usr/bin/env bash
# Operational step-cost measurement (TASK92, STEPCOST_OP_DESIGN.md): every
# (artifact, plan) lifecycle through run_multiturn.sh -- the multi-turn
# runner, server arguments and streaming path -- with a 40 s evaluation window.
#
#   run_stepcost_op.sh <RUN_DIR_ABS>
#
# Order: seeded shuffle (20261810) of all decode and prefill lifecycles, then
# the reproducibility repeats (TUNED n4, n8). A failed lifecycle is retried
# once under "<tag>.retry1". Resumable via run_multiturn.sh's done markers.
# Do not edit this file or anything it calls while it runs (KNOWN_PITFALLS 5).
set -uo pipefail
RUN="$1"
REPO=/home/rebel/continuum-npu
case "$RUN" in /*) ;; *) echo "RUN must be absolute"; exit 64 ;; esac
mkdir -p "$RUN"
S3="$REPO/experiments/npu/stage3"
PLANS="$S3/plans/stepcost"
declare -A ART=(
  [BASE]="$REPO/models/Qwen3-4B-rbln-b8-s8192-d4-mb"
  [BATCHONLY]="$REPO/models/Qwen3-4B-rbln-b16-s8192-d4-batchonly"
  [TUNED]="$REPO/models/Qwen3-4B-rbln-b16-s8192-d4-mb16"
  [DP]="$REPO/models/Qwen3-4B-rbln-b16-s8192-d4-dp8"
)
git -C "$REPO" rev-parse HEAD >> "$RUN/git-head.txt"
[ -f "$RUN/measurement-start.txt" ] || date -Is > "$RUN/measurement-start.txt"
rbln-stat > "$RUN/rbln-stat-before.$(date +%s).txt" 2>&1
bash "$REPO/patches/vllm_rbln-0.11.1/apply.sh" status > "$RUN/patch-before.$(date +%s).txt" 2>&1

mapfile -t ITEMS < <(python3 - <<'PYEOF'
import random
items = [("BASE", f"op-decode-n{n}") for n in range(1, 9)]
for cfg in ("BATCHONLY", "TUNED", "DP"):
    items += [(cfg, f"op-decode-n{n}") for n in (1, 2, 3, 4, 5, 6, 7, 8, 10, 12, 14, 16)]
items += [(cfg, "op-prefill") for cfg in ("BASE", "BATCHONLY", "TUNED", "DP")]
random.Random(20261810).shuffle(items)
items += [("TUNED", "op-decode-n4"), ("TUNED", "op-decode-n8")]
seen = {}
for cfg, pid in items:
    seen[(cfg, pid)] = seen.get((cfg, pid), 0) + 1
    rep = "" if seen[(cfg, pid)] == 1 else ".rep2"
    print(cfg, pid, f"{cfg}.{pid}{rep}")
PYEOF
)

for item in "${ITEMS[@]}"; do
  set -- $item
  CFG="$1"; PID="$2"; TAG="$3"
  echo "=== $TAG $(date -Is)"
  bash "$S3/run_multiturn.sh" "$RUN" "$TAG" "${ART[$CFG]}" "$PLANS/$PID.json" stream 40
  if [ ! -f "$RUN/done.$TAG" ]; then
    echo "$TAG failed, retrying once"
    bash "$S3/run_multiturn.sh" "$RUN" "$TAG.retry1" "${ART[$CFG]}" "$PLANS/$PID.json" stream 40
  fi
done
date -Is > "$RUN/measurement-end.txt"
rbln-stat > "$RUN/rbln-stat-after.txt" 2>&1
bash "$REPO/patches/vllm_rbln-0.11.1/apply.sh" status > "$RUN/patch-after.txt" 2>&1
echo "STEPCOST DONE"
